import React, { useState, useEffect, useContext } from 'react';
import {
    Card, Button, Box, Typography, Grid, IconButton, Fab, Dialog, DialogTitle, DialogContent,
    DialogActions, CardContent, Modal, Chip, Tooltip
} from '@mui/material';
import { db } from '../db/db';
import { MainContext } from '../context/MainContext';
import HelpOutlineIcon from '@mui/icons-material/HelpOutline';
import AddIcon from '@mui/icons-material/Add';
import RemoveIcon from '@mui/icons-material/Remove';
import CheckIcon from '@mui/icons-material/Check';

const ObservationForm = ({ speciesOptions, onCancel }) => {
    const { formData, setFormData, addOrUpdateSpecies, setPhase } = useContext(MainContext);
    const [selectedSpecies, setSelectedSpecies] = useState(null);
    const [observationData, setObservationData] = useState({
        collecte: 0,
        comportement: 0,
        tdenom: 'IND',
        methode: 0,
        mort: 0,
        protocole: 0,
        stade: 0,
        statutbio: 0,
        denom: 'Co'
    });
    const [trouveMort, setTrouveMort] = useState(0);
    const [mort, setMort] = useState('');
    const [maleCount, setMaleCount] = useState(0);
    const [femaleCount, setFemaleCount] = useState(0);
    const [undeterminedCount, setUndeterminedCount] = useState(0);
    const [open, setOpen] = useState(false);
    const [openDialog, setOpenDialog] = useState(false);
    const [species, setSpecies] = useState([]);
    const [showMaleCount, setShowMaleCount] = useState(true);
    const [showFemaleCount, setShowFemaleCount] = useState(true);
    const [showUndeterminedCount, setShowUndeterminedCount] = useState(true);

    // Charger les espèces depuis le fichier JSON et les ordonner par leur valeur "rang"
    useEffect(() => {
        fetch(`${process.env.PUBLIC_URL}/especes.json`)
            .then(response => response.json())
            .then(data => {
                const sortedData = data.sort((a, b) => a.rang - b.rang);
                setSpecies(sortedData);
            })
            .catch(error => console.error('Erreur lors du chargement des espèces:', error));
    }, []);

    const MonthTimeline = ({ espece, months }) => {
        const monthNames = [
            { key: "janvier", name: "Janvier" },
            { key: "fevrier", name: "Février" },
            { key: "mars", name: "Mars" },
            { key: "avril", name: "Avril" },
            { key: "mai", name: "Mai" },
            { key: "juin", name: "Juin" },
            { key: "juillet", name: "Juillet" },
            { key: "aout", name: "Août" },
            { key: "septembre", name: "Septembre" },
            { key: "octobre", name: "Octobre" },
            { key: "novembre", name: "Novembre" },
            { key: "decembre", name: "Décembre" },
        ];

        return (
            <Box
                sx={{
                    padding: 2,
                    background: '#f9f9f9',
                    borderRadius: '8px',
                    boxShadow: '0 2px 8px rgba(0, 0, 0, 0.1)',
                    maxWidth: '95%',
                    textAlign: 'center',
                }}
            >
                {/* Timeline */}
                <Grid container spacing={1} justifyContent="center">
                    {monthNames.map(({ key, name }, index) => (
                        <Grid item key={index} xs={3} sm={2} md={1} sx={{
                            display: 'flex',
                            flexDirection: 'column',
                            alignItems: 'center',
                        }}
                        >
                            <Tooltip title={name}>
                                <Box
                                    sx={{
                                        width: '30px',
                                        height: '30px',
                                        borderRadius: '50%',
                                        backgroundColor: months[key] === "1" ? '#81c784' : '#e0e0e0',
                                        display: 'flex',
                                        justifyContent: 'center',
                                        alignItems: 'center',
                                        fontWeight: 'bold',
                                        color: months[key] === "1" ? '#ffffff' : '#575757',
                                        boxShadow: months[key] === "1" ? '0 2px 4px rgba(0, 0, 0, 0.2)' : 'none',
                                    }}
                                >
                                    <Typography fontSize={10} sx={{ fontWeight: 'bold' }} > {name.substring(0, 3).toUpperCase()}</Typography> {/* Affichage des 3 premières lettres du mois */}
                                </Box>
                            </Tooltip>
                        </Grid>
                    ))}
                </Grid>
            </Box>
        );
    };

    const handleSave = () => {
        // Construction des données d'observation pour un stade spécifique
        const formattedObservationData = {
            nom: selectedSpecies.latin,
            cdnom: selectedSpecies.cdnom,
            nomvern: selectedSpecies.espece,
            rqobs: '',
            observatoire: 'ornitho',
            stade: 2,
            trouveMort,
            mort: 0,
            maleCount,
            femaleCount,
            undeterminedCount,
            denom: 'Co',
            tdenom: 'IND',
            methode: 1,
            protocole: 1,
            statutbio: 0,
            comportement: observationData.comportement, //posé passage en vol, etc
            collecte: 1
        };
        addOrUpdateSpecies(selectedSpecies.cdnom, formattedObservationData);
        console.log('formattedObservationData', formattedObservationData);
        handleClose();
    };

    const handleCardClick = async (item) => {
        setSelectedSpecies(item);
        setMaleCount(0);
        setFemaleCount(0);
        setUndeterminedCount(0);
        setOpen(true);
    };

    const handleClose = () => setOpen(false);

    // Fonction pour ouvrir le dialogue
    const handleOpenDialog = () => {
        setOpenDialog(true);
    };

    // Fonction pour fermer le dialogue
    const handleCloseDialog = () => {
        setOpenDialog(false);
    };

    const handleCount = (item) => {
        setShowMaleCount(!!item.imageF);
        setShowFemaleCount(!!item.imageF);
    }

    const handleValidate = () => {
        setPhase('synthese');
    }

    return (
        <Box
            sx={{
                minHeight: '100vh',
                display: 'flex',
                flexDirection: 'column',
                alignItems: 'center',
                justifyContent: 'center',
                background: 'linear-gradient(135deg, #ffecb3, #ffcc80)',
                padding: 1,
                fontFamily: 'Poppins, sans-serif',
            }}
        >
            <Box sx={{
                display: 'flex', justifyContent: 'space-between',
                marginTop: 16, borderRadius: 8,

            }}>

                {/* Bouton pour ouvrir le dialogue */}
                <Fab size="small" color="primary" aria-label="help" onClick={handleOpenDialog} style={{ position: 'fixed', bottom: 50, right: 16 }}>
                    <HelpOutlineIcon />
                </Fab>
                {/* Dialogue pour afficher les conseils */}
                <Dialog open={openDialog} onClose={handleCloseDialog}>
                    <DialogTitle>Conseils d'utilisation</DialogTitle>
                    <DialogContent>
                        <p>Choisissez l'oiseau que vous pensez avoir observé. Une fenêtre s'ouvrira avec des informations sur l'espèce.</p>
                        <p>Pour certaines espèces, vous aurez la possibilité de consulter les images des mâles et des femelles si des différences morphologiques existent.</p> <p>Une fois que vous avez défini le nombre, validez votre sélection. Vous ne pouvez enregistrer qu'une seule fois la même espèce.</p>
                        <p>Si vous sélectionnez à nouveau une espèce déjà choisie, cela remplacera les données précédemment saisies.</p>
                    </DialogContent>
                    <DialogActions>
                        <Button onClick={handleCloseDialog}>Fermer</Button>
                    </DialogActions>
                </Dialog>

                <Grid container spacing={2} padding={1}>
                    {species.map((item, index) => (
                        <Grid item xs={12} sm={4} md={3} key={index}>
                            <Card elevation={3}
                                sx={{ height: 200, cursor: 'pointer', display: 'flex', flexDirection: 'column', justifyContent: 'center', alignItems: 'center', position: 'relative' }}
                                onClick={() => { handleCount(item); handleCardClick(item); }}
                            >
                                <Box sx={{
                                    width: 200,
                                    height: 200,
                                    backgroundImage: `url(${process.env.PUBLIC_URL + '/images/' + item.image})`,
                                    backgroundSize: 'contain',
                                    backgroundPosition: 'center',
                                }}
                                >
                                    {item.cdnom in formData.especes && (
                                        <Chip
                                            label="Espèce enregistrée"
                                            icon={<CheckIcon />}
                                            color="primary"
                                            sx={{
                                                position: 'absolute',
                                                top: 6,
                                                right: 6,
                                            }}
                                        />
                                    )}
                                </Box>
                                <CardContent sx={{
                                    padding: '1px', textAlign: 'center',
                                    position: 'absolute', bottom: 0,
                                    width: '100%', backgroundColor: 'rgba(0, 0, 0, 0.5)'
                                }}>
                                    <Typography variant="h6" sx={{ color: 'white' }}>
                                        {item.espece}
                                    </Typography>
                                </CardContent>
                            </Card>
                        </Grid>
                    ))}
                </Grid>

                <Fab onClick={handleValidate} sx={{ bgcolor: '#38d355' }} variant="extended"
                    style={{ position: 'fixed', top: 100, right: 16 }}>
                    Voir le récapitulatif avant validation
                    <CheckIcon onClick={handleValidate} />
                </Fab>
                <Modal open={open} onClose={handleClose} aria-labelledby="modal-title" aria-describedby="modal-description">
                    <Box sx={{ position: 'fixed', left: '5%', right: '10%', top: '10%', bottom: '10%', bgcolor: 'background.paper', boxShadow: 24, p: 4, overflowY: 'auto' }}>
                        <Grid container spacing={2}>
                            {selectedSpecies?.imageF ? (
                                <Grid container spacing={2}>
                                    <Grid item xs={12} align="center">
                                        <Typography variant="h5">{selectedSpecies?.espece} <i>{selectedSpecies?.latin}</i></Typography>
                                    </Grid>
                                    <Grid item xs={6} align="center"> <Box
                                        sx={{
                                            width: 200,
                                            height: 200,
                                            backgroundImage: `url(${process.env.PUBLIC_URL + '/images/' + selectedSpecies?.image})`,
                                            backgroundSize: 'contain',
                                            backgroundPosition: 'center',
                                            backgroundRepeat: 'no-repeat',
                                            margin: '0 auto'
                                        }}
                                    />
                                        <Typography variant="h6">Mâle</Typography>
                                    </Grid>
                                    <Grid item xs={6} align="center">
                                        <Box
                                            sx={{
                                                width: 200,
                                                height: 200,
                                                backgroundImage: `url(${process.env.PUBLIC_URL + '/images/' + selectedSpecies?.imageF})`,
                                                backgroundSize: 'contain',
                                                backgroundPosition: 'center',
                                                backgroundRepeat: 'no-repeat',
                                                margin: '0 auto'
                                            }}
                                        />
                                        <Typography variant="h6">Femelle</Typography>
                                    </Grid>
                                </Grid>
                            ) : (
                                <Grid item xs={12} align="center">
                                    <Typography variant="h5">{selectedSpecies?.espece} <i>{selectedSpecies?.latin}</i></Typography>
                                    <Box
                                        sx={{
                                            width: 200,
                                            height: 200,
                                            backgroundImage: `url(${process.env.PUBLIC_URL + '/images/' + selectedSpecies?.image})`,
                                            backgroundSize: 'contain',
                                            backgroundPosition: 'center',
                                            backgroundRepeat: 'no-repeat',
                                            margin: '0 auto'
                                        }}
                                    />
                                </Grid>
                            )}
                            <Grid item xs={12}>
                                <Typography variant="h6">Période de présence</Typography>
                                <MonthTimeline
                                    espece={selectedSpecies?.espece}
                                    months={selectedSpecies}
                                />
                            </Grid>
                            {/* Description de l'espèce */}
                            <Grid item xs={8}>
                                <Typography variant="h6">Description</Typography>
                                <Typography>{selectedSpecies?.description}</Typography>
                            </Grid>
                            {/* Informations sur le poids, la taille et l'envergure */}
                            <Grid item xs={4}>
                                <Typography variant="h6">Informations</Typography>
                                <Typography>Poids : {selectedSpecies?.poids}gr</Typography>
                                <Typography>Taille : {selectedSpecies?.longueur}cm</Typography>
                                <Typography>Envergure : {selectedSpecies?.envergure}cm</Typography>
                            </Grid>

                            {/* Encart sur les confusions à éviter */}
                            <Grid item xs={12}>
                                <Typography variant="h6">Confusions à éviter</Typography>
                                <Typography>{selectedSpecies?.texte}</Typography>
                            </Grid>

                            {/* Sélecteurs numériques pour le dénombrement */}
                            <Grid item xs={12}>
                                <Typography id="modal-title" variant="h5" component="h2">
                                    Combien avez-vous vu de {selectedSpecies?.espece} ?
                                </Typography>
                                <Grid container spacing={2} justifyContent="center" alignItems="center">
                                    {showMaleCount && (
                                        <Grid item xs={4} align="center">
                                            <Typography>Mâles</Typography>
                                            <IconButton onClick={() => setMaleCount(maleCount + 1)} sx={{ bgcolor: 'success.main', color: 'white', '&:hover': { bgcolor: 'primary.dark' }, width: 40, height: 40, borderRadius: '50%' }}>
                                                <AddIcon />
                                            </IconButton>
                                            <Typography>{maleCount}</Typography>
                                            <IconButton onClick={() => setMaleCount(maleCount - 1)} sx={{ bgcolor: 'error.main', color: 'white', '&:hover': { bgcolor: 'primary.dark' }, width: 40, height: 40, borderRadius: '50%' }}>
                                                <RemoveIcon />
                                            </IconButton>
                                        </Grid>
                                    )}
                                    {showFemaleCount && (
                                        <Grid item xs={4} align="center">
                                            <Typography>Femelles</Typography>
                                            <IconButton onClick={() => setFemaleCount(femaleCount + 1)} sx={{ bgcolor: 'success.main', color: 'white', '&:hover': { bgcolor: 'primary.dark' }, width: 40, height: 40, borderRadius: '50%' }}>
                                                <AddIcon />
                                            </IconButton>
                                            <Typography>{femaleCount}</Typography>
                                            <IconButton onClick={() => setFemaleCount(femaleCount - 1)} sx={{ bgcolor: 'error.main', color: 'white', '&:hover': { bgcolor: 'primary.dark' }, width: 40, height: 40, borderRadius: '50%' }}>
                                                <RemoveIcon />
                                            </IconButton>
                                        </Grid>
                                    )}

                                    <Grid item xs={4} align="center">
                                        <Typography>Sexe non déterminable</Typography>
                                        <IconButton onClick={() => setUndeterminedCount(undeterminedCount + 1)} sx={{ bgcolor: 'success.main', color: 'white', '&:hover': { bgcolor: 'primary.dark' }, width: 40, height: 40, borderRadius: '50%' }}>
                                            <AddIcon />
                                        </IconButton>
                                        <Typography>{undeterminedCount}</Typography>
                                        <IconButton onClick={() => setUndeterminedCount(undeterminedCount - 1)} sx={{ bgcolor: 'error.main', color: 'white', '&:hover': { bgcolor: 'primary.dark' }, width: 40, height: 40, borderRadius: '50%' }}>
                                            <RemoveIcon />
                                        </IconButton>
                                    </Grid>
                                </Grid>
                            </Grid>
                        </Grid>
                        <Grid container spacing={2} justifyContent="center">
                            <Grid item xs={6} align="center">
                                <Button onClick={handleClose} variant="outlined" color="error" sx={{ mt: 2, ml: 2 }}>
                                    Annuler
                                </Button>
                            </Grid>
                            <Grid item xs={6} align="center">
                                <Button onClick={handleSave} variant="contained" color="primary" sx={{ mt: 2 }}>
                                    Enregistrer
                                </Button>
                            </Grid>
                        </Grid>
                    </Box>
                </Modal >
            </Box >
        </Box >
    );
};

export default ObservationForm;
