import React, { useContext, useState, useEffect } from 'react';
import { Card, CardContent, Button, Box, CardHeader, Chip, Grid } from '@mui/material';
import { db } from '../db/db';
import { useNavigate } from 'react-router-dom';
import SyncIcon from '@mui/icons-material/Sync';
import { MainContext } from '../context/MainContext';

export default function Parametre() {
    const [status, setStatus] = useState('');
    const navigate = useNavigate();
    const { fetchUser
    } = useContext(MainContext);
    //Vider le user
    async function handleClearDbUser() {
        try {
            await db.user.clear();
            setStatus('Base de données des utilisateurs vidée');

        } catch (error) {
            setStatus(`Échec du vidage de la base de données: ${error}`);
        }
        fetchUser();
    }
    return (
        <Box
            sx={{
                minHeight: '100vh',
                display: 'flex',
                flexDirection: 'column',
                alignItems: 'left',
                justifyContent: 'center',
                background: 'linear-gradient(135deg, #ffecb3, #ffcc80)',
                padding: 3,
                fontFamily: 'Poppins, sans-serif',
            }}
        >
            <Card sx={{ marginBottom: 1 }}>
                <CardHeader
                    title="Bienvenue sur SkolOBS"
                    subheader="Si c'est votre première connexion voici quelques conseils"
                />
                <CardContent>
                    Utilisez le menu de navigation pour accéder aux différentes sections de l'application. Vous pouvez consulter vos observations, ajouter de nouvelles observations, et accéder à des ressources utiles.
                </CardContent>
            </Card>
            <Card sx={{ marginBottom: 1 }}>
                <CardHeader
                    title="Ajouter une observation"
                    subheader="Vous allez pouvoir saisir des données d'observations faune et flore"
                />
                <CardContent>
                    Pour ajouter une nouvelle observation, cliquez sur le bouton "Saisir des observations"
                </CardContent>
            </Card>
            <Card sx={{ marginBottom: 1 }}>
                <CardHeader
                    title="Ajouter une observation"
                    subheader="Vous allez pouvoir saisir des données d'observations faune et flore"
                />
                <CardContent
                    sx={{ display: 'flex', alignItems: 'center', justifyContent: 'center' }}
                >
                    <Button variant="contained" onClick={() => navigate("/skolobs")} color="primary">
                        C'est parti !
                    </Button>
                </CardContent>
            </Card>
            <Grid container spacing={2}>
                <Grid item xs={12} sm={6} md={4}>
                    <Chip
                        label="Changer d'utilisateur"
                        onClick={handleClearDbUser}
                        onDelete={handleClearDbUser}
                        deleteIcon={<SyncIcon />}
                        color="secondary"
                    />
                </Grid>
            </Grid>
        </Box>
    );
};

