import React, { useContext, useState } from 'react';
import { Card, TextField, FormControl, InputLabel, Select, MenuItem, Button, Box, Typography, Switch, IconButton, Grid, Fab, DialogContent, Dialog, DialogTitle, DialogActions } from '@mui/material';
import { MainContext } from '../context/MainContext';
import InfoIcon from '@mui/icons-material/Info';
import HelpOutlineIcon from '@mui/icons-material/HelpOutline';
import { useNavigate } from 'react-router-dom';
import { useEffect } from 'react';
import Dexie from 'dexie';
import { db } from '../db/db';


const FicheForm = ({ organismes, etudes, onCancel }) => {
    const { formData, setFormData, updatePhase, setPhase, updateFormData, clickedPosition, selectedSite } = useContext(MainContext);
    const [open, setOpen] = useState(false);
    const navigate = useNavigate();
    const [userData, setUserData] = useState({});

    useEffect(() => {
        const fetchUserData = async () => {
            try {
                const user = await db.user.toCollection().first();
                if (user) {
                    setUserData(user);
                }
            } catch (error) {
                console.error('Failed to fetch user data from Dexie', error);
            }
        };
        fetchUserData();
    }, []);

    useEffect(() => {
        console.log('userData', userData);
    }, [userData]);

    //Mise a jour a la validation
    const handleSubmit = (event) => {
        event.preventDefault();
        // Mettre à jour les données de la fiche dans le contexte
        const newFormData = {
            ...formData,
            fiche: {
                ...formData.fiche,
                date1: formData.fiche.date || null,
                date2: formData.fiche.date2 || null,
                organisme: 2,
                typeDonnee: 'Pu',
                diffusion: 0,
                site: userData.site || null,
                idsite: userData.idsite || null,
                newsite: false,
                idcoord: userData.idcoord || null,
                etude: userData.etude || null,
                idm: userData.idm || null,
                idobser: userData.idobser || null,
                lat: userData.lat || null,
                long: userData.lng || null
            }
        };
        updateFormData(newFormData);
        console.log('newFormData', newFormData)
        setPhase('observation');
    };

    // Fonction pour ouvrir le dialogue
    const handleOpenDialog = () => {
        console.log('selectedsite', selectedSite)
        setOpen(true);
    };

    // Fonction pour fermer le dialogue
    const handleCloseDialog = () => {
        setOpen(false);
    };

    const [selectedCard, setSelectedCard] = useState(null); // État pour suivre la carte sélectionnée

    const handleCardClick = (cardId) => {
        setSelectedCard(cardId); // Mettre à jour l'état avec l'ID de la carte sélectionnée
    };

    return (
        <Box
            sx={{
                minHeight: '100vh',
                display: 'flex',
                flexDirection: 'column',
                alignItems: 'center',
                justifyContent: 'center',
                background: 'linear-gradient(135deg, #ffecb3, #ffcc80)',
                padding: 1,
                fontFamily: 'Poppins, sans-serif',
                paddingTop:10
            }}
        >
            <Card sx={{ padding: 2, borderRadius: 8 }}>
                {/* Bouton pour ouvrir le dialogue */}
                <Fab color="primary" aria-label="help" onClick={handleOpenDialog} style={{ position: 'fixed', bottom: 16, left: 16 }}>
                    <HelpOutlineIcon />
                </Fab>
                {/* Dialogue pour afficher les conseils */}
                <Dialog open={open} onClose={handleCloseDialog}>
                    <DialogTitle>Conseils d'utilisation</DialogTitle>
                    <DialogContent>
                        <p>La date par défaut est celle du jour</p>
                    </DialogContent>
                    <DialogActions>
                        <Button onClick={handleCloseDialog}>Fermer</Button>
                    </DialogActions>
                </Dialog>
                <Typography variant="h5">Date d'observation</Typography>
                <form onSubmit={handleSubmit}>
                    <Grid container spacing={2} direction="row" justifyContent="center" alignItems="center">
                        <Grid item xs={6}>
                            <TextField
                                label="Date du jour"
                                type="date"
                                value={formData.fiche.date}
                                onChange={(e) => setFormData({
                                    ...formData,
                                    fiche: { ...formData.fiche, date: e.target.value }
                                })}
                                InputLabelProps={{ shrink: true }}
                                fullWidth
                                margin="normal"
                            />
                        </Grid>
                    </Grid>
                </form>
                <Box sx={{ display: 'flex', direction: 'row', justifyContent: 'center', margin: 1 }}>
                    <Grid container spacing={2} sx={{ padding: 1, justifyContent: 'center', alignItems: 'center' }}>
                        <Grid item xs={12} sx={{ justifyContent: 'center', alignItems: 'center' }}>
                            <Typography variant="h5">Dans quelles conditions avez-vous réalisé ces observations</Typography>
                        </Grid>
                        <Grid item xs={6} md={6} sx={{ display: 'flex', justifyContent: 'center', alignItems: 'center' }}>
                            <Card elevation={3} sx={{
                                height: 220, cursor: 'pointer', display: 'flex', flexDirection: 'column', justifyContent: 'center', alignItems: 'center', padding: 2,
                                backgroundColor: selectedCard === 'sol' ? 'lightblue' : 'white'
                            }}
                                onClick={() => handleCardClick('sol')}>
                                <Typography variant="h6">Observations au sol ou en vol</Typography>
                                <Box
                                    sx={{
                                        width: 200,
                                        height: 200,
                                        backgroundImage: `url(${process.env.PUBLIC_URL + '/icones/oiso.png'})`,
                                        backgroundSize: 'contain',
                                        backgroundPosition: 'center',
                                    }}
                                />
                            </Card>
                        </Grid>
                        <Grid item xs={6} md={6}
                            sx={{ display: 'flex', justifyContent: 'center', alignItems: 'center' }}>
                            <Card elevation={3}
                                sx={{
                                    height: 220, cursor: 'pointer', display: 'flex',
                                    flexDirection: 'column', justifyContent: 'center',
                                    alignItems: 'center', padding: 2, backgroundColor: selectedCard === 'mangeoire' ? 'lightblue' : 'white'
                                }}
                                onClick={() => handleCardClick('mangeoire')}>
                                <Typography variant="h6">Observations à la mangeoire</Typography>
                                <Box
                                    sx={{
                                        width: 200,
                                        height: 200,
                                        backgroundImage: `url(${process.env.PUBLIC_URL + '/icones/mangeoire.png'})`,
                                        backgroundSize: 'contain',
                                        backgroundPosition: 'center',
                                    }}
                                />
                            </Card>
                        </Grid>
                        <Grid item xs={6} md={6}>
                            <Button onClick={() => navigate('/')}>
                                <Typography variant="outlined" color="secondary">Annuler</Typography>
                            </Button>
                        </Grid>
                        <Grid item xs={6} md={6}>
                            <Button variant="contained" color="primary" onClick={handleSubmit}>
                                Valider
                            </Button>
                        </Grid>
                    </Grid>
                </Box>
            </Card>
        </Box>
    );
};

export default FicheForm;
