import React, { useContext, useEffect } from 'react';
import AppBar from '@mui/material/AppBar';
import Box from '@mui/material/Box';
import Toolbar from '@mui/material/Toolbar';
import Typography from '@mui/material/Typography';
import { useNavigate } from 'react-router-dom';
import { MainContext } from '../context/MainContext';

export default function Navbar() {
  const { user, fetchUser } = useContext(MainContext);
  const navigate = useNavigate();

  useEffect(() => {
    fetchUser();
  }, []);


  return (
    <AppBar position="absolute" sx={{ top: 20, left: 16, backgroundColor: 'transparent', boxShadow: 'none' }}>
      <Toolbar>
         <Box component="img"
            src={`${process.env.PUBLIC_URL + '/icones/loutre.png'}`}
            alt="App Logo"
            sx={{ height: 100, cursor: 'pointer', position: 'absolute', top: '60%', transform: 'translateY(-50%)' }}
            onClick={() => navigate('/')}
          />
       
      </Toolbar>
    </AppBar>
  );
}
